import numpy as np #importa a biblioteca numpy e a renomeia como np para facilitar o acesso às suas funções e recursos
m = np.array([[1,2,3],[4,5,6]]) #cria uma matriz 2x3 usando a função array do numpy, onde a primeira linha contém os números 1, 2 e 3, e a segunda linha contém os números 4, 5 e 6
print(m[0,1]) #acessa o elemento na primeira linha e segunda coluna e printa o resultado que é 2